$ErrorActionPreference='Stop'
$installer=Join-Path $PSScriptRoot 'Install-RepatoV1.ps1';$dry=& powershell -NoProfile -ExecutionPolicy Bypass -File $installer -Action DryRun -RepoRoot (Split-Path $PSScriptRoot -Parent)|ConvertFrom-Json
if($dry.TargetDll -notmatch 'Autodesk\\Revit\\Addins\\2025\\Repato\\Repato.Revit.dll'){throw 'DryRun target mismatch.'}
$scratch=Join-Path ([IO.Path]::GetTempPath()) ('repato-installer-'+[guid]::NewGuid().ToString('N'));$repo=Join-Path $scratch 'repo';$app=Join-Path $scratch 'appdata';$old=$env:APPDATA
try{New-Item (Join-Path $repo 'bin\Release\net8.0-windows') -ItemType Directory -Force|Out-Null;Set-Content (Join-Path $repo 'bin\Release\net8.0-windows\Repato.Revit.dll') 'release';Set-Content (Join-Path $repo 'Repato.addin') 'production';$target=Join-Path $app 'Autodesk\Revit\Addins\2025\Repato';$parent=Split-Path $target -Parent;New-Item $target -ItemType Directory -Force|Out-Null;Set-Content (Join-Path $target 'old.dll') 'old';Set-Content (Join-Path $parent 'Repato.addin') 'old-manifest';$env:APPDATA=$app;$install=& $installer -Action Install -RepoRoot $repo;if(!(Test-Path (Join-Path $target 'Repato.Revit.dll')) -or !(Test-Path (Join-Path $parent 'Repato.addin')) -or !(Test-Path  $install.Backup)){throw 'Isolated install or backup failed.'};if(!(Test-Path (Join-Path $install.Backup 'Repato')) -or !(Test-Path (Join-Path $install.Backup 'Repato.addin'))){throw 'Backup contents are incomplete.'};& $installer -Action Uninstall -RepoRoot $repo|Out-Null;if(Test-Path $target){throw 'Uninstall left temporary installation.'};Write-Host 'Repato v1 installer regression passed.'}finally{$env:APPDATA=$old;if(Test-Path $scratch){Remove-Item $scratch -Recurse -Force}}
